// ---------------------------------------------------------------------------------
// DOM patching (keeps scroll position and focused inputs intact)

function syncAttributes(from, to) {
  for (const a of [...from.attributes]) if (!to.hasAttribute(a.name)) from.removeAttribute(a.name);
  for (const a of [...to.attributes]) if (from.getAttribute(a.name) !== a.value) from.setAttribute(a.name, a.value);
}

function morphNode(from, to) {
  if (from.nodeType !== to.nodeType || from.nodeName !== to.nodeName ||
      (from.nodeType === 1 && (from.getAttribute('data-key') || '') !== (to.getAttribute('data-key') || ''))) {
    from.replaceWith(to.cloneNode(true));
    return;
  }
  if (from.nodeType === 3 || from.nodeType === 8) {
    if (from.nodeValue !== to.nodeValue) from.nodeValue = to.nodeValue;
    return;
  }
  if (from.hasAttribute && from.hasAttribute('data-static') && to.hasAttribute('data-static')) return;
  syncAttributes(from, to);
  const focused = document.activeElement === from;
  if (from.tagName === 'INPUT') {
    if (from.type === 'checkbox' || from.type === 'radio') from.checked = to.hasAttribute('checked');
    else if (!focused && from.value !== (to.getAttribute('value') ?? '')) from.value = to.getAttribute('value') ?? '';
    return;
  }
  if (from.tagName === 'TEXTAREA') {
    if (!focused && from.value !== to.textContent) from.value = to.textContent;
    return;
  }
  morphChildren(from, to);
  if (from.tagName === 'SELECT') {
    const sel = to.querySelector('option[selected]');
    const v = sel ? sel.getAttribute('value') : (to.querySelector('option')?.getAttribute('value') ?? '');
    if (from.value !== v) from.value = v;
  }
}

function morphChildren(from, to) {
  const a = [...from.childNodes];
  const b = [...to.childNodes];
  for (let i = 0; i < b.length; i++) {
    if (i < a.length) morphNode(a[i], b[i]);
    else from.appendChild(b[i].cloneNode(true));
  }
  for (let i = a.length - 1; i >= b.length; i--) a[i].remove();
}

export function patch(container, html) {
  const tpl = document.createElement('template');
  tpl.innerHTML = html;
  const tmp = document.createElement(container.tagName);
  tmp.append(tpl.content);
  morphChildren(container, tmp);
}

// ---------------------------------------------------------------------------------
// Views & event delegation

let seq = 0;
export const registry = new Map();

export class View {
  constructor() { this.id = 'v' + (++seq); this.actions = {}; this.inputs = {}; this.changes = {}; registry.set(this.id, this); }
  render() { return ''; }
  destroy() { registry.delete(this.id); }
}

function viewFor(el) {
  const host = el.closest('[data-view]');
  return host ? registry.get(host.getAttribute('data-view')) : null;
}

let suppressClickUntil = 0;

export function installDelegation(root) {
  // The click that follows a long-press must not reach the menu/sheet that just opened
  // (iOS delivers it to whatever is now under the finger).
  window.addEventListener('click', (ev) => {
    if (Date.now() < suppressClickUntil) { ev.preventDefault(); ev.stopPropagation(); }
  }, true);
  root.addEventListener('click', (ev) => {
    const el = ev.target.closest('[data-act]');
    if (!el || el.disabled || el.getAttribute('aria-disabled') === 'true') return;
    const view = viewFor(el);
    const fn = view && view.actions[el.getAttribute('data-act')];
    if (fn) { ev.preventDefault(); fn.call(view, el, ev); }
  });
  const handle = (kind) => (ev) => {
    const attr = kind === 'input' ? 'data-input' : 'data-change';
    const el = ev.target.closest(`[${attr}]`);
    if (!el) return;
    const view = viewFor(el);
    const map = view && (kind === 'input' ? view.inputs : view.changes);
    const fn = map && map[el.getAttribute(attr)];
    if (fn) fn.call(view, el, ev);
  };
  root.addEventListener('input', handle('input'));
  root.addEventListener('change', handle('change'));

  // Long press → data-longpress action
  let lp = null;
  root.addEventListener('pointerdown', (ev) => {
    const el = ev.target.closest('[data-longpress]');
    if (!el) return;
    const x = ev.clientX, y = ev.clientY;
    lp = { el, x, y, timer: setTimeout(() => {
      const view = viewFor(el);
      const fn = view && view.actions[el.getAttribute('data-longpress')];
      if (fn) { suppressClickUntil = Date.now() + 700; fn.call(view, el, ev); }
      lp = null;
    }, 550) };
  });
  const cancel = () => { if (lp) { clearTimeout(lp.timer); lp = null; } };
  root.addEventListener('pointerup', cancel);
  root.addEventListener('pointercancel', cancel);
  root.addEventListener('pointermove', (ev) => { if (lp && Math.hypot(ev.clientX - lp.x, ev.clientY - lp.y) > 10) cancel(); });
  root.addEventListener('scroll', cancel, true);
  root.addEventListener('contextmenu', (ev) => { if (ev.target.closest('[data-longpress]')) ev.preventDefault(); });
}

// ---------------------------------------------------------------------------------
// Modal layer: sheets, alerts, menus

const modals = [];
let modalRoot = null;
let onModalsChanged = () => {};
export function initModals(root, onChange) { modalRoot = root; onModalsChanged = onChange; }

export function renderModals() {
  for (const m of modals) {
    const body = m.el.querySelector('[data-view]');
    patch(body, m.view.render());
  }
}

/** opts: { height: 'auto'|'large'|number, dismissable } */
export function presentSheet(view, opts = {}) {
  const wrap = document.createElement('div');
  wrap.className = 'modal sheet-wrap';
  const h = opts.height === 'large' ? 'sheet-large' : opts.height === 'full' ? 'sheet-full' : '';
  wrap.innerHTML = `<div class="backdrop" data-close></div><div class="sheet ${h}"><div class="grabber"></div><div class="sheet-body" data-view="${view.id}"></div></div>`;
  modalRoot.appendChild(wrap);
  const entry = { el: wrap, view, opts };
  modals.push(entry);
  view.close = () => dismiss(entry);
  patch(wrap.querySelector('[data-view]'), view.render());
  if (view.mounted) view.mounted(wrap.querySelector('[data-view]'));
  wrap.querySelector('[data-close]').addEventListener('click', () => { if (opts.dismissable !== false) dismiss(entry); });
  attachSheetDrag(wrap, entry);
  requestAnimationFrame(() => wrap.classList.add('open'));
  onModalsChanged();
  return view;
}

function attachSheetDrag(wrap, entry) {
  const sheet = wrap.querySelector('.sheet');
  const grab = wrap.querySelector('.grabber');
  let startY = null, dy = 0;
  grab.addEventListener('pointerdown', (e) => { startY = e.clientY; dy = 0; grab.setPointerCapture(e.pointerId); sheet.style.transition = 'none'; });
  grab.addEventListener('pointermove', (e) => { if (startY == null) return; dy = Math.max(0, e.clientY - startY); sheet.style.transform = `translateY(${dy}px)`; });
  const end = () => {
    if (startY == null) return;
    sheet.style.transition = ''; sheet.style.transform = '';
    if (dy > 90 && entry.opts.dismissable !== false) dismiss(entry);
    startY = null;
  };
  grab.addEventListener('pointerup', end);
  grab.addEventListener('pointercancel', end);
}

export function dismiss(entry) {
  const i = modals.indexOf(entry);
  if (i < 0) return;
  modals.splice(i, 1);
  entry.el.classList.remove('open');
  entry.el.classList.add('closing');
  setTimeout(() => entry.el.remove(), 260);
  if (entry.view.onDismiss) entry.view.onDismiss();
  entry.view.destroy();
  onModalsChanged();
}
export function dismissAll() { while (modals.length) dismiss(modals[modals.length - 1]); }
export const hasModals = () => modals.length > 0;

class AlertView extends View {
  constructor(opts) { super(); this.opts = opts; this.actions.btn = (el) => this.press(Number(el.dataset.i)); }
  render() {
    const { title, message, buttons } = this.opts;
    const stacked = buttons.length > 2;
    return `<div class="alert-title">${esc(title)}</div>${message ? `<div class="alert-msg">${esc(message).replace(/\n/g, '<br>')}</div>` : ''}
      <div class="alert-buttons ${stacked ? 'stacked' : ''}">${buttons.map((b, i) => `<button class="alert-btn ${b.role || ''}" data-act="btn" data-i="${i}">${esc(b.label)}</button>`).join('')}</div>`;
  }
  press(i) { const b = this.opts.buttons[i]; this.close(); if (b && b.handler) b.handler(); }
}

/** buttons: [{label, role: 'cancel'|'destructive'|'default', handler}] */
export function alert(title, message, buttons = [{ label: 'OK' }]) {
  const view = new AlertView({ title, message, buttons });
  const wrap = document.createElement('div');
  wrap.className = 'modal alert-wrap';
  wrap.innerHTML = `<div class="backdrop"></div><div class="alert" data-view="${view.id}"></div>`;
  modalRoot.appendChild(wrap);
  const entry = { el: wrap, view, opts: { dismissable: false } };
  modals.push(entry);
  view.close = () => dismiss(entry);
  patch(wrap.querySelector('[data-view]'), view.render());
  requestAnimationFrame(() => wrap.classList.add('open'));
  onModalsChanged();
}
export function confirm(title, message, confirmLabel, onConfirm, destructive = true) {
  alert(title, message, [{ label: 'Cancel', role: 'cancel' }, { label: confirmLabel, role: destructive ? 'destructive' : 'default', handler: onConfirm }]);
}

class MenuView extends View {
  constructor(title, items) { super(); this.title = title; this.items = items; this.actions.pick = (el) => { const it = this.items[Number(el.dataset.i)]; this.close(); if (it && it.handler) it.handler(); }; this.actions.cancel = () => this.close(); }
  render() {
    return `<div class="menu-card">${this.title ? `<div class="menu-title">${esc(this.title)}</div>` : ''}${this.items.map((it, i) =>
      `<button class="menu-item ${it.destructive ? 'destructive' : ''}" data-act="pick" data-i="${i}">${it.icon ? icon[it.icon] : ''}<span>${esc(it.label)}</span></button>`).join('')}</div>
      <button class="menu-cancel" data-act="cancel">Cancel</button>`;
  }
}
/** items: [{label, icon?, destructive?, handler}] */
export function menu(items, title = '') {
  const view = new MenuView(title, items.filter(Boolean));
  const wrap = document.createElement('div');
  wrap.className = 'modal menu-wrap';
  wrap.innerHTML = `<div class="backdrop" data-close></div><div class="menu" data-view="${view.id}"></div>`;
  modalRoot.appendChild(wrap);
  const entry = { el: wrap, view, opts: {} };
  modals.push(entry);
  view.close = () => dismiss(entry);
  patch(wrap.querySelector('[data-view]'), view.render());
  wrap.querySelector('[data-close]').addEventListener('click', () => dismiss(entry));
  requestAnimationFrame(() => wrap.classList.add('open'));
  onModalsChanged();
}

let toastTimer = null;
export function toast(text, kind = '') {
  let el = document.getElementById('toast');
  if (!el) { el = document.createElement('div'); el.id = 'toast'; document.body.appendChild(el); }
  el.className = `toast show ${kind}`;
  el.textContent = text;
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => { el.className = 'toast'; }, 2600);
}

// ---------------------------------------------------------------------------------
// Common fragments

export function sheetHeader(title, { left = 'Cancel', right = null, rightDisabled = false, leftAct = 'cancel', rightAct = 'done' } = {}) {
  return `<div class="sheet-header">
    <button class="link-btn" data-act="${leftAct}">${left ? esc(left) : ''}</button>
    <div class="sheet-title">${esc(title)}</div>
    <button class="link-btn strong" data-act="${rightAct}" ${rightDisabled ? 'disabled' : ''}>${right ? esc(right) : ''}</button>
  </div>`;
}

export function pill(text, cls) { return `<span class="pill ${cls}">${esc(text)}</span>`; }

export function statTile(label, value, sub = null, cls = '') {
  return `<div class="tile ${cls}"><div class="tile-label">${esc(label)}</div><div class="tile-value">${esc(value)}</div>${sub ? `<div class="tile-sub">${esc(sub)}</div>` : ''}</div>`;
}

export function trendBadge(trend, higherIsBetter = null) {
  const ic = trend.dir === 'up' ? icon.trendUp : trend.dir === 'down' ? icon.trendDown : icon.trendFlat;
  let cls = 'neutral';
  if (higherIsBetter != null && trend.dir !== 'neutral') cls = (trend.dir === 'up') === higherIsBetter ? 'good' : 'bad';
  return `<span class="trend ${cls}">${ic}<span>${esc(trend.text)}</span></span>`;
}

export function emptyState(title, message, ic = 'list') {
  return `<div class="empty">${icon[ic] || ''}<div class="empty-title">${esc(title)}</div><div class="empty-msg">${esc(message)}</div></div>`;
}

export function stepper(label, value, act, min, max) {
  return `<div class="row stepper-row"><span>${esc(label)}</span><div class="stepper">
    <button class="step-btn" data-act="${act}" data-d="-1" ${value <= min ? 'disabled' : ''}>${icon.minus}</button>
    <button class="step-btn" data-act="${act}" data-d="1" ${value >= max ? 'disabled' : ''}>${icon.plus}</button></div></div>`;
}

export function toggle(label, on, change, sub = '') {
  return `<label class="row toggle-row"><span class="grow">${esc(label)}${sub ? `<span class="row-sub">${esc(sub)}</span>` : ''}</span>
    <input type="checkbox" class="switch" data-change="${change}" ${on ? 'checked' : ''}></label>`;
}

// ---------------------------------------------------------------------------------
// Line chart (plain X/Y, one colour)

function niceTicks(min, max, count = 4) {
  if (min === max) { const pad = Math.abs(min) * 0.05 || 1; min -= pad; max += pad; }
  const span = max - min;
  const raw = span / count;
  const mag = Math.pow(10, Math.floor(Math.log10(raw)));
  const step = [1, 2, 2.5, 5, 10].map((m) => m * mag).find((s) => s >= raw) || raw;
  const lo = Math.floor(min / step) * step, hi = Math.ceil(max / step) * step;
  const ticks = [];
  for (let v = lo; v <= hi + step / 2; v += step) ticks.push(Number(v.toFixed(6)));
  return { lo, hi, ticks };
}

export function lineChart(points, { unit = '', decimals = 1, includeZero = false, color = 'var(--accent)' } = {}) {
  if (points.length < 2) return `<div class="chart-empty">Not enough data for a chart yet.</div>`;
  const W = Math.round(clamp(window.innerWidth, 320, 640) - 58), H = 160;
  const padL = 40, padR = 8, padT = 8, padB = 22;
  const xs = points.map((p) => +p.date), ys = points.map((p) => p.value);
  let minY = Math.min(...ys), maxY = Math.max(...ys);
  if (includeZero) minY = Math.min(0, minY);
  const { lo, hi, ticks } = niceTicks(minY, maxY);
  const minX = Math.min(...xs), maxX = Math.max(...xs);
  const sx = (x) => padL + (maxX === minX ? (W - padL - padR) / 2 : ((x - minX) / (maxX - minX)) * (W - padL - padR));
  const sy = (y) => padT + (hi === lo ? (H - padT - padB) / 2 : (1 - (y - lo) / (hi - lo)) * (H - padT - padB));
  const grid = ticks.map((t) => `<line x1="${padL}" x2="${W - padR}" y1="${sy(t)}" y2="${sy(t)}" class="grid"/><text x="${padL - 6}" y="${sy(t) + 3.5}" class="axis" text-anchor="end">${esc(fmt.number(t, decimals))}</text>`).join('');
  const nX = Math.min(4, points.length);
  const xl = [];
  for (let i = 0; i < nX; i++) {
    const x = minX + ((maxX - minX) * i) / Math.max(1, nX - 1);
    const anchor = i === 0 ? 'start' : i === nX - 1 ? 'end' : 'middle';
    xl.push(`<text x="${sx(x)}" y="${H - 5}" class="axis" text-anchor="${anchor}">${esc(fmt.dayMonth(x))}</text>`);
  }
  const path = points.map((p, i) => `${i ? 'L' : 'M'}${sx(+p.date).toFixed(1)},${sy(p.value).toFixed(1)}`).join(' ');
  const dots = points.map((p) => `<circle cx="${sx(+p.date).toFixed(1)}" cy="${sy(p.value).toFixed(1)}" r="2.6" fill="${color}"><title>${esc(fmt.dayMonth(p.date))}: ${esc(fmt.number(p.value, decimals))} ${esc(unit)}</title></circle>`).join('');
  return `<svg class="chart" viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Chart">${grid}${xl.join('')}<path d="${path}" fill="none" stroke="${color}" stroke-width="1.6"/>${dots}</svg>`;
}

// ---------------------------------------------------------------------------------
// Weight keypad (typed value, decimal support, configurable quick increments)

export class WeightKeypad extends View {
  constructor({ initial = 0, override = null, title = 'Weight', showApply = true, onDone }) {
    super();
    this.text = initial > 0 ? fmt.editable(initial) : '';
    this.override = override; this.title = title; this.showApply = showApply; this.apply = false; this.onDone = onDone;
    this.actions = {
      cancel: () => this.close(),
      key: (el) => this.key(el.dataset.k),
      inc: (el) => { const v = Math.max(0, this.value + Number(el.dataset.v)); this.text = fmt.editable(Math.round(v * 100) / 100); this.refresh(); },
      apply: () => { this.apply = !this.apply; this.refresh(); },
      done: () => { const v = Math.round(this.value * 100) / 100; this.close(); this.onDone(v, this.apply); },
    };
  }
  get value() { return parseDecimal(this.text) ?? 0; }
  key(k) {
    if (k === 'del') this.text = this.text.slice(0, -1);
    else if (k === '.') { if (!this.text.includes('.')) this.text += this.text ? '.' : '0.'; }
    else if (this.text === '0') this.text = k;
    else if (this.text.length < 7) this.text += k;
    this.refresh();
  }
  refresh() { const el = document.querySelector(`[data-view="${this.id}"]`); if (el) patch(el, this.render()); }
  render() {
    const incs = DB.signedIncrements(this.override);
    return `${sheetHeader(this.title, { right: null })}
      <div class="keypad-display"><span class="kp-value">${esc(this.text || '0')}</span><span class="kp-unit">kg</span></div>
      <div class="inc-row">${incs.map((v) => `<button class="inc-btn" data-act="inc" data-v="${v}">${v > 0 ? '+' : '−'}${esc(fmt.number(Math.abs(v), 2))}</button>`).join('')}</div>
      ${keypadGrid(true)}
      ${this.showApply ? `<button class="check-row" data-act="apply">${this.apply ? icon.check : icon.circle}<span>Apply to remaining sets of this exercise</span></button>` : ''}
      <button class="btn primary" data-act="done">Done</button>`;
  }
}

export function keypadGrid(decimal) {
  const keys = ['1', '2', '3', '4', '5', '6', '7', '8', '9', decimal ? '.' : '', '0', 'del'];
  return `<div class="keypad">${keys.map((k) => k === '' ? '<span></span>' : `<button class="key" data-act="key" data-k="${k}">${k === 'del' ? icon.backspace : k}</button>`).join('')}</div>`;
}

// ---------------------------------------------------------------------------------
// Reps wheel 0–12 (+ Custom for larger values)

const ITEM_H = 44;
export class RepsPicker extends View {
  constructor({ initial = 0, target = [8, 12], onDone }) {
    super();
    this.target = target; this.onDone = onDone;
    this.custom = initial > 12;
    this.customText = initial > 12 ? String(initial) : '';
    this.selection = initial > 12 ? 13 : Math.max(0, initial);
    this.actions = {
      cancel: () => this.close(),
      key: (el) => {
        const k = el.dataset.k;
        if (k === 'del') this.customText = this.customText.slice(0, -1);
        else if (this.customText.length < 3) this.customText = this.customText === '0' ? k : this.customText + k;
        this.refresh();
      },
      back: () => { this.custom = false; this.selection = Math.min(12, parseInt(this.customText, 10) || 0); this.refresh(); this.scrollToSelection(); },
      pickItem: (el) => { const i = Number(el.dataset.i); if (i === 13) { this.custom = true; this.refresh(); } else { this.selection = i; this.scrollToSelection(true); } },
      done: () => {
        if (!this.custom) this.selection = this.readWheel();
        const reps = this.custom ? (parseInt(this.customText, 10) || 0) : this.selection === 13 ? 0 : this.selection;
        if (!this.custom && this.selection === 13) { this.custom = true; this.refresh(); return; }
        this.close(); this.onDone(Math.max(0, reps));
      },
    };
  }
  refresh() { const el = document.querySelector(`[data-view="${this.id}"]`); if (el) { patch(el, this.render()); this.bindWheel(el); } }
  readWheel() {
    const w = document.querySelector(`[data-view="${this.id}"] .wheel`);
    if (!w) return this.selection;
    return clamp(Math.round(w.scrollTop / ITEM_H), 0, 13);
  }
  scrollToSelection(smooth = false) {
    requestAnimationFrame(() => {
      const w = document.querySelector(`[data-view="${this.id}"] .wheel`);
      if (w) w.scrollTo({ top: this.selection * ITEM_H, behavior: smooth ? 'smooth' : 'auto' });
      this.highlight();
    });
  }
  highlight() {
    const w = document.querySelector(`[data-view="${this.id}"] .wheel`);
    if (!w) return;
    const i = clamp(Math.round(w.scrollTop / ITEM_H), 0, 13);
    w.querySelectorAll('.wheel-item').forEach((el, k) => el.classList.toggle('sel', k === i));
  }
  bindWheel(root) {
    const w = root.querySelector('.wheel');
    if (!w || w._bound) return;
    w._bound = true;
    let t = null;
    w.addEventListener('scroll', () => {
      this.highlight();
      clearTimeout(t);
      t = setTimeout(() => {
        const i = this.readWheel();
        this.selection = i;
        if (i === 13) { this.custom = true; this.refresh(); }
      }, 160);
    }, { passive: true });
  }
  mounted(root) { this.bindWheel(root); this.scrollToSelection(); }
  render() {
    const [lo, hi] = this.target;
    const tText = lo === hi ? `Target ${lo}` : `Target ${lo}–${hi}`;
    const head = `<div class="sheet-header"><button class="link-btn" data-act="cancel">Cancel</button><div class="sheet-title">Reps <span class="muted small">${esc(tText)}</span></div><span class="link-btn"></span></div>`;
    if (this.custom) {
      return `${head}<div class="keypad-display"><span class="kp-value">${esc(this.customText || '0')}</span><span class="kp-unit">reps</span></div>
        ${keypadGrid(false)}<button class="link-btn center" data-act="back">Back to 0–12</button><button class="btn primary" data-act="done">Done</button>`;
    }
    const items = [];
    for (let n = 0; n <= 12; n++) items.push(`<div class="wheel-item ${n >= lo && n <= hi ? 'in-target' : ''}" data-act="pickItem" data-i="${n}">${n}</div>`);
    items.push(`<div class="wheel-item custom" data-act="pickItem" data-i="13">Custom</div>`);
    return `${head}<div class="wheel-wrap" data-static><div class="wheel-band"></div><div class="wheel">${'<div class="wheel-pad"></div>'}${items.join('')}<div class="wheel-pad"></div></div></div>
      <button class="btn primary" data-act="done">Done</button>`;
  }
}

// ---------------------------------------------------------------------------------
// Saving files (share sheet when available → "Save to Files")

export async function saveFile(name, data, mime = 'application/octet-stream') {
  const blob = data instanceof Blob ? data : new Blob([data], { type: mime });
  try {
    const file = new File([blob], name, { type: mime });
    if (navigator.canShare && navigator.canShare({ files: [file] })) {
      await navigator.share({ files: [file] });
      return 'shared';
    }
  } catch (e) {
    if (e && e.name === 'AbortError') return 'cancelled';
  }
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = name; a.rel = 'noopener';
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 30000);
  return 'downloaded';
}

export function pickFile(accept = '') {
  return new Promise((resolve) => {
    const input = document.createElement('input');
    input.type = 'file';
    if (accept) input.accept = accept;
    input.style.display = 'none';
    input.addEventListener('change', () => { resolve(input.files && input.files[0] ? input.files[0] : null); input.remove(); });
    document.body.appendChild(input);
    input.click();
  });
}

// Dates, formatting and small helpers. All day logic uses the device's local time zone.
// Weekdays use the same numbering as the iPhone app: 1 = Sunday ... 7 = Saturday.

export const MS_DAY = 86400000;
const LOCALE = 'en-GB';

export function uuid() {
  if (crypto.randomUUID) return crypto.randomUUID().toUpperCase();
  const b = crypto.getRandomValues(new Uint8Array(16));
  b[6] = (b[6] & 0x0f) | 0x40; b[8] = (b[8] & 0x3f) | 0x80;
  const h = [...b].map((x) => x.toString(16).padStart(2, '0')).join('');
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20)}`.toUpperCase();
}

export const pad2 = (n) => String(n).padStart(2, '0');

export function toDate(x) { return x instanceof Date ? x : new Date(x); }

/** 'YYYY-MM-DD' in local time. */
export function dayKey(x = Date.now()) {
  const d = toDate(x);
  return `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`;
}
export function parseDay(key) {
  const [y, m, d] = key.split('-').map(Number);
  return new Date(y, m - 1, d);
}
export const todayKey = () => dayKey(new Date());
export function startOfDay(x) { const d = toDate(x); return new Date(d.getFullYear(), d.getMonth(), d.getDate()); }
export function addDays(x, n) { const d = startOfDay(x); d.setDate(d.getDate() + n); return d; }
export function addDaysKey(key, n) { return dayKey(addDays(parseDay(key), n)); }
export function setTime(x, hour, minute) { const d = startOfDay(x); d.setHours(hour, minute, 0, 0); return d; }
export function isToday(x) { return dayKey(x) === todayKey(); }
/** 1 = Sunday ... 7 = Saturday */
export function weekday(x) { return (typeof x === 'string' ? parseDay(x) : toDate(x)).getDay() + 1; }
export function daysBetween(a, b) {
  const ka = typeof a === 'string' ? parseDay(a) : startOfDay(a);
  const kb = typeof b === 'string' ? parseDay(b) : startOfDay(b);
  return Math.round((kb - ka) / MS_DAY);
}
/** Weeks start on Monday (UK). */
export const ORDERED_WEEKDAYS = [2, 3, 4, 5, 6, 7, 1];
export function startOfWeek(x) {
  const d = startOfDay(x);
  const offset = (d.getDay() + 6) % 7; // Monday = 0
  d.setDate(d.getDate() - offset);
  return d;
}
export function startOfMonth(x) { const d = toDate(x); return new Date(d.getFullYear(), d.getMonth(), 1); }
export function addMonths(x, n) { const d = startOfMonth(x); d.setMonth(d.getMonth() + n); return d; }
export function endOfMonth(x) { return addDays(addMonths(x, 1), -1); }
export function daysInRange(fromKey, toKey) {
  const out = [];
  let d = parseDay(fromKey);
  const end = parseDay(toKey);
  while (d <= end) { out.push(dayKey(d)); d.setDate(d.getDate() + 1); }
  return out;
}

const WD_LONG = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const WD_SHORT = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
export function weekdayName(wd, short = false) {
  const i = Math.max(0, Math.min(6, wd - 1));
  return short ? WD_SHORT[i] : WD_LONG[i];
}

const nf = {};
function numberFormat(dec) {
  if (!nf[dec]) nf[dec] = new Intl.NumberFormat(LOCALE, { minimumFractionDigits: 0, maximumFractionDigits: dec });
  return nf[dec];
}
const dtf = (opts) => new Intl.DateTimeFormat(LOCALE, opts);
const F_DAY_MONTH = dtf({ day: 'numeric', month: 'short' });
const F_DAY_MONTH_YEAR = dtf({ day: 'numeric', month: 'short', year: 'numeric' });
const F_WD_DAY_MONTH = dtf({ weekday: 'short', day: 'numeric', month: 'short' });
const F_FULL = dtf({ weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
const F_MONTH_YEAR = dtf({ month: 'long', year: 'numeric' });
const F_TIME = dtf({ hour: '2-digit', minute: '2-digit' });

const asDate = (x) => (typeof x === 'string' ? parseDay(x) : toDate(x));

export const fmt = {
  number(v, dec = 1) { return numberFormat(dec).format(v); },
  integer(v) { return numberFormat(0).format(Math.round(v)); },
  kg(v) { return numberFormat(2).format(v) + ' kg'; },
  /** Locale-independent value for editable fields. */
  editable(v) {
    const r = Math.round(v * 100) / 100;
    if (Number.isInteger(r)) return String(r);
    return r.toFixed(2).replace(/0+$/, '').replace(/\.$/, '');
  },
  target(sets, repMin, repMax) { return repMin === repMax ? `${sets} × ${repMin}` : `${sets} × ${repMin}–${repMax}`; },
  duration(sec) {
    const t = Math.max(0, Math.round(sec));
    const h = Math.floor(t / 3600), m = Math.floor((t % 3600) / 60), s = t % 60;
    return h > 0 ? `${h}:${pad2(m)}:${pad2(s)}` : `${m}:${pad2(s)}`;
  },
  minutes(sec) {
    const m = Math.round(sec / 60);
    return m >= 60 ? `${Math.floor(m / 60)} h ${m % 60} min` : `${m} min`;
  },
  feetInches(total) {
    const feet = Math.floor(total / 12);
    const inches = Math.round(total - feet * 12);
    return `${feet}′ ${inches}″`;
  },
  dayMonth(x) { return F_DAY_MONTH.format(asDate(x)); },
  dayMonthYear(x) { return F_DAY_MONTH_YEAR.format(asDate(x)); },
  weekdayDayMonth(x) { return F_WD_DAY_MONTH.format(asDate(x)); },
  fullDate(x) { return F_FULL.format(asDate(x)); },
  monthYear(x) { return F_MONTH_YEAR.format(asDate(x)); },
  time(x) { return F_TIME.format(asDate(x)); },
  reminderTime(minutes) { return `${pad2(Math.floor(minutes / 60))}:${pad2(minutes % 60)}`; },
  bytes(n) {
    if (n < 1000) return `${n} bytes`;
    if (n < 1e6) return `${numberFormat(0).format(n / 1000)} KB`;
    return `${numberFormat(1).format(n / 1e6)} MB`;
  },
};

export function norm(s) { return String(s || '').trim().toLowerCase().replace(/\s+/g, ' '); }

export function esc(s) {
  return String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

/** Parse a user-typed decimal ("62,5" or "62.5"). Returns null when empty or invalid. */
export function parseDecimal(text) {
  const t = String(text ?? '').trim().replace(',', '.');
  if (!t) return null;
  const v = Number(t);
  return Number.isFinite(v) ? v : null;
}

export function minutesToTimeInput(m) { return `${pad2(Math.floor(m / 60))}:${pad2(m % 60)}`; }
export function timeInputToMinutes(v, fallback) {
  const m = /^(\d{1,2}):(\d{2})/.exec(v || '');
  return m ? Number(m[1]) * 60 + Number(m[2]) : fallback;
}

export function clamp(v, lo, hi) { return Math.min(hi, Math.max(lo, v)); }
export const sum = (arr, f = (x) => x) => arr.reduce((a, x) => a + f(x), 0);
export function maxBy(arr, better) {
  let best = undefined;
  for (const x of arr) if (best === undefined || better(x, best)) best = x;
  return best;
}

// Body tab: manual weekly check-ins (weight, height, age, optional body fat / waist / note).

import * as DB from '../db.js';
import { Q, Stats, changed } from '../engine.js';
import { nav, Screen } from '../nav.js';
import { View, icon, statTile, trendBadge, lineChart, emptyState, sheetHeader, menu, confirm, presentSheet, patch, stepper } from '../ui.js';
import { esc, fmt, uuid, addDays, startOfWeek, dayKey, parseDay, parseDecimal } from '../util.js';

const RANGES = [['4W', 28], ['3M', 91], ['1Y', 365], ['All', null]];

function bmi(e) {
  if (e.weightKg == null || !e.heightInches) return null;
  const m = e.heightInches * 0.0254;
  return e.weightKg / (m * m);
}
function bmiBand(v) { return v < 18.5 ? 'underweight' : v < 25 ? 'normal' : v < 30 ? 'overweight' : 'obese'; }
const heightText = (e) => (e && e.heightInches ? fmt.feetInches(e.heightInches) : null);

export class BodyScreen extends Screen {
  constructor(title = 'Body') {
    super(title);
    this.range = '3M';
    Object.assign(this.actions, {
      add: () => presentSheet(new BodyEntrySheet(Q.bodyStats()[0] || null, null), { height: 'large' }),
      edit: (el) => { const e = DB.state.bodyStats.get(el.dataset.id); if (e) presentSheet(new BodyEntrySheet(Q.bodyStats()[0], e), { height: 'large' }); },
      entryMenu: (el) => {
        const e = DB.state.bodyStats.get(el.dataset.id); if (!e) return;
        menu([
          { label: 'Edit entry', icon: 'pencil', handler: () => presentSheet(new BodyEntrySheet(Q.bodyStats()[0], e), { height: 'large' }) },
          { label: 'Delete entry', icon: 'trash', destructive: true, handler: () => confirm('Delete this entry?', `${fmt.dayMonthYear(e.date)} — ${e.weightKg != null ? fmt.kg(e.weightKg) : 'no weight'}. This cannot be undone.`, 'Delete', () => { DB.remove('bodyStats', e.id); changed(); }) },
        ]);
      },
      range: (el) => { this.range = el.dataset.r; nav.refresh(); },
    });
  }
  render() {
    const entries = Q.bodyStats();
    const latest = entries[0];
    const days = RANGES.find((r) => r[0] === this.range)[1];
    const chrono = [...entries].reverse();
    const ranged = days ? chrono.filter((e) => e.date >= addDays(new Date(), -days).getTime()) : chrono;
    const weekStart = startOfWeek(new Date()).getTime();
    const doneThisWeek = entries.some((e) => e.date >= weekStart);
    const s = DB.settings();

    const checkIn = `<div class="card">
      <div class="row-between"><div><div class="headline">Weekly check-in</div>
        <div class="caption ${doneThisWeek ? 'text-completed' : 'muted'}">${doneThisWeek ? `Done for this week — updated ${esc(fmt.dayMonthYear(latest.date))}` : s.fridayReminderEnabled ? `Due this week · reminder Fridays ${fmt.reminderTime(s.fridayReminderMinutes)}` : 'Due this week'}</div></div>
        <span class="big-check ${doneThisWeek ? 'on' : ''}">${doneThisWeek ? icon.check : icon.circle}</span></div>
      <button class="btn primary" data-act="add">${doneThisWeek ? 'ADD ANOTHER ENTRY' : "ADD THIS WEEK'S UPDATE"}</button>
    </div>`;
    if (!entries.length) return `<div class="stack">${checkIn}<div class="card">${emptyState('No entries yet', 'Add your first weekly check-in to start tracking body weight, height and more.', 'body')}</div></div>`;

    const weights = entries.map((e) => e.weightKg).filter((v) => v != null);
    let delta = null;
    if (weights.length >= 2) { const d = weights[0] - weights[1]; delta = Math.abs(d) < 0.05 ? 'no change' : `${d > 0 ? '+' : ''}${fmt.number(d, 1)} kg vs last`; }
    const b = latest ? bmi(latest) : null;
    const current = `<div class="section-label">Current</div>
      <div class="tiles">${statTile('Weight', latest.weightKg != null ? fmt.kg(latest.weightKg) : '—', delta)}${statTile('Height', heightText(latest) || '—')}${statTile('Age', latest.age != null ? String(latest.age) : '—')}</div>
      <div class="tiles">${statTile('BMI', b != null ? fmt.number(b, 1) : '—', b != null ? bmiBand(b) : null)}${statTile('Body fat', latest.bodyFatPercent != null ? `${fmt.number(latest.bodyFatPercent, 1)}%` : '—')}${statTile('Waist', latest.waistCm != null ? `${fmt.number(latest.waistCm, 1)} cm` : '—')}</div>`;

    const wv = ranged.map((e) => e.weightKg).filter((v) => v != null);
    const wTrend = Stats.trend(wv, 1);
    const wStats = wv.length >= 2 ? `<div class="caption faint num chart-foot">Start ${esc(fmt.kg(wv[0]))} · Now ${esc(fmt.kg(wv[wv.length - 1]))} · Change ${wv[wv.length - 1] - wv[0] > 0 ? '+' : ''}${fmt.number(wv[wv.length - 1] - wv[0], 1)} kg · Range ${fmt.number(Math.min(...wv), 1)}–${fmt.number(Math.max(...wv), 1)}</div>` : '';
    const weightCard = `<div class="card"><div class="row-between"><span class="sub strong">Body weight</span>${trendBadge(wTrend, null)}</div>
      <div class="segmented small">${RANGES.map(([r]) => `<button class="seg ${this.range === r ? 'on' : ''}" data-act="range" data-r="${r}">${r}</button>`).join('')}</div>
      ${lineChart(ranged.filter((e) => e.weightKg != null).map((e) => ({ date: e.date, value: e.weightKg })), { unit: 'kg' })}${wStats}</div>`;

    const extraChart = (title, unit, key) => {
      const pts = ranged.filter((e) => e[key] != null).map((e) => ({ date: e.date, value: e[key] }));
      if (!pts.length) return '';
      return `<div class="card"><div class="row-between"><span class="sub strong">${title}</span>${trendBadge(Stats.trend(pts.map((p) => p.value), 1), null)}</div>${lineChart(pts, { unit })}</div>`;
    };

    const weeks = [0, 1, 2].map((i) => Stats.weekSummary(addDays(new Date(), -7 * i)));
    const training = `<div class="card"><div class="label">Training — last 3 weeks</div>${weeks.map((w) => `<div class="week-row">
      <div class="row-between"><span class="sub strong">Week of ${esc(fmt.dayMonth(w.weekStart))}</span><span class="caption muted">${w.completedSessions}/${w.sessions} workouts</span></div>
      <div class="caption faint num">${w.sets} sets · ${fmt.integer(w.volume)} kg volume · ${fmt.minutes(w.duration)}</div>
      ${w.topLifts.length ? `<div class="caption muted clamp2">${w.topLifts.slice(0, 3).map((l) => `${esc(l.name)} ${fmt.number(l.weight, 1)}×${l.reps}`).join(' · ')}</div>` : ''}</div>`).join('')}</div>`;

    const list = `<div class="card"><div class="row-between"><span class="label">All entries</span><span class="caption faint">${entries.length}</span></div>
      ${entries.map((e) => {
        const extras = [e.bodyFatPercent != null ? `BF ${fmt.number(e.bodyFatPercent, 1)}%` : null, e.waistCm != null ? `waist ${fmt.number(e.waistCm, 1)} cm` : null, e.note || null].filter(Boolean);
        return `<button class="entry-row" data-act="edit" data-id="${e.id}" data-longpress="entryMenu">
          <div class="row-between"><span class="sub muted">${esc(fmt.dayMonthYear(e.date))}</span><span class="row-left num"><span class="sub strong">${e.weightKg != null ? esc(fmt.kg(e.weightKg)) : '—'}</span><span class="sub muted">${esc(heightText(e) || '—')}</span><span class="sub muted">${e.age != null ? `${e.age} y` : '—'}</span>${icon.chevron}</span></div>
          ${extras.length ? `<div class="caption faint ellipsis">${esc(extras.join(' · '))}</div>` : ''}</button>`;
      }).join('')}
      <div class="caption faint">Tap an entry to edit it. Long-press to delete.</div></div>`;

    return `<div class="stack">${checkIn}${current}${weightCard}${extraChart('Body fat', '%', 'bodyFatPercent')}${extraChart('Waist', 'cm', 'waistCm')}${training}${list}</div>`;
  }
}

class BodyEntrySheet extends View {
  constructor(previous, editing) {
    super();
    this.editing = editing;
    const src = editing || previous;
    this.date = dayKey(editing ? editing.date : Date.now());
    this.weightText = src && src.weightKg != null ? fmt.editable(src.weightKg) : '';
    const totalIn = src && src.heightInches ? Math.round(src.heightInches) : 70;
    this.feet = Math.min(7, Math.max(3, Math.floor(totalIn / 12)));
    this.inches = Math.min(11, Math.max(0, totalIn - this.feet * 12));
    this.age = src && src.age != null ? src.age : 30;
    this.bf = editing && editing.bodyFatPercent != null ? fmt.editable(editing.bodyFatPercent) : '';
    this.waist = editing && editing.waistCm != null ? fmt.editable(editing.waistCm) : '';
    this.note = editing && editing.note ? editing.note : '';
    this.error = null;
    this.actions = {
      cancel: () => this.close(),
      done: () => this.save(),
      age: (el) => { this.age = Math.min(100, Math.max(10, this.age + Number(el.dataset.d))); this.refresh(); },
    };
    this.inputs = {
      weight: (el) => { this.weightText = el.value; }, bf: (el) => { this.bf = el.value; },
      waist: (el) => { this.waist = el.value; }, note: (el) => { this.note = el.value; },
    };
    this.changes = {
      date: (el) => { if (el.value) this.date = el.value; },
      feet: (el) => { this.feet = Number(el.value); }, inches: (el) => { this.inches = Number(el.value); },
    };
  }
  refresh() { const el = document.querySelector(`[data-view="${this.id}"]`); if (el) patch(el, this.render()); }
  save() {
    const w = parseDecimal(this.weightText);
    if (this.weightText.trim() && w == null) return this.fail('Weight must be a number.');
    if (w != null && (w <= 0 || w > 400)) return this.fail('Weight must be between 0 and 400 kg.');
    const bf = parseDecimal(this.bf);
    if (this.bf.trim() && bf == null) return this.fail('Body fat must be a number.');
    if (bf != null && (bf < 1 || bf > 70)) return this.fail('Body fat must be between 1 and 70%.');
    const wc = parseDecimal(this.waist);
    if (this.waist.trim() && wc == null) return this.fail('Waist must be a number.');
    if (wc != null && (wc < 30 || wc > 250)) return this.fail('Waist must be between 30 and 250 cm.');
    if (this.date > dayKey(Date.now())) return this.fail("The date can't be in the future.");
    const note = this.note.trim();
    const day = parseDay(this.date);
    const now = new Date();
    // Keep the time of day for entries made today; otherwise noon on the chosen day.
    const date = this.date === dayKey(now) ? now.getTime() : (this.editing && dayKey(this.editing.date) === this.date ? this.editing.date : new Date(day.getFullYear(), day.getMonth(), day.getDate(), 12).getTime());
    const record = {
      id: this.editing ? this.editing.id : uuid(), date, weightKg: w, heightInches: this.feet * 12 + this.inches, age: this.age,
      bodyFatPercent: bf, waistCm: wc, note: note || null, isDemo: this.editing ? this.editing.isDemo : DB.demo.active,
    };
    DB.put('bodyStats', record);
    changed();
    this.close();
  }
  fail(msg) { this.error = msg; this.refresh(); }
  render() {
    const opt = (from, to, sel, unit) => { let h = ''; for (let i = from; i <= to; i++) h += `<option value="${i}" ${i === sel ? 'selected' : ''}>${i} ${unit}</option>`; return h; };
    return `${sheetHeader(this.editing ? 'Edit entry' : 'Weekly update', { right: 'Save' })}
      <div class="list grouped form">
        <label class="row"><span class="row-label grow">Date</span><input type="date" class="date-input" value="${this.date}" max="${dayKey(Date.now())}" data-change="date"></label>
        <label class="row"><span class="row-label grow">Body weight</span><input class="num-input" inputmode="decimal" placeholder="kg" value="${esc(this.weightText)}" data-input="weight"><span class="unit">kg</span></label>
        <div class="row"><span class="row-label grow">Height</span><select class="select" data-change="feet">${opt(3, 7, this.feet, 'ft')}</select><select class="select" data-change="inches">${opt(0, 11, this.inches, 'in')}</select></div>
        ${stepper(`Age: ${this.age}`, this.age, 'age', 10, 100)}
      </div>
      <div class="section-label">Optional</div>
      <div class="list grouped form">
        <label class="row"><span class="row-label grow">Body fat</span><input class="num-input" inputmode="decimal" placeholder="—" value="${esc(this.bf)}" data-input="bf"><span class="unit">%</span></label>
        <label class="row"><span class="row-label grow">Waist</span><input class="num-input" inputmode="decimal" placeholder="—" value="${esc(this.waist)}" data-input="waist"><span class="unit">cm</span></label>
        <label class="row"><input class="text-input full" placeholder="Note (e.g. morning, after breakfast)" value="${esc(this.note)}" data-input="note"></label>
      </div>
      ${this.error ? `<div class="caption text-missed">${esc(this.error)}</div>` : ''}`;
  }
}

